css:
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --blue: #002868; --blue-dark: #001a45; --blue-light: #eff6ff;
      --red: #E31E24; --gold: #f59e0b; --green: #10b981; --green-light: #d1fae5;
      --text: #111827; --text-muted: #6b7280; --border: #e5e7eb;
      --bg: #f9fafb; --bg-alt: #f0f4ff; --white: #fff; --sidebar-w: 280px; --topbar-h: 60px;
      /* One shared width for the video, the lesson card and the nav bar so
         the reading column lines up instead of three different measures. */
      --content-w: 900px;
    }
    html, body { height: 100%; overflow: hidden; }
    body {
      font-family: 'Inter', sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #f8fbff 0%, #f3f6fb 45%, #eef4ff 100%);
      display: flex;
      flex-direction: column;
    }
    /* Issue 1 fix: overflow safety nets so no horizontal scroll strip appears */
    .player-layout { overflow-x: hidden; }
    .main-area { overflow-x: hidden; }
    a { text-decoration: none; color: inherit; }

    /* TOP BAR */
    .topbar {
      height: var(--topbar-h);
      background: rgba(255,255,255,0.94);
      border-bottom: 1px solid rgba(229,231,235,0.9);
      backdrop-filter: blur(10px);
      box-shadow: 0 6px 20px rgba(2, 24, 68, 0.06);
      display: flex;
      align-items: center;
      padding: 0 1rem;
      gap: 1rem;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
    }
    .topbar-left { display: flex; align-items: center; gap: 0.75rem; flex-shrink: 0; }
    /* Issue 2 fix: topbar-back minimum 44px tap target */
    .topbar-back { display: flex; align-items: center; gap: 0.35rem; color: var(--text-muted); font-size: 0.83rem; font-weight: 500; transition: color .2s; padding: 0.35rem 0.5rem; border-radius: 6px; white-space: nowrap; min-height: 44px; }
    .topbar-back:hover { color: var(--blue); background: var(--blue-light); }
    .topbar-divider { width: 1px; height: 20px; background: var(--border); }
    .topbar-brand { font-family: 'Poppins', sans-serif; font-weight: 800; color: var(--blue); font-size: 1rem; white-space: nowrap; }
    .topbar-brand span { color: var(--red); }
    .topbar-center { flex: 1; display: flex; align-items: center; gap: 0.75rem; min-width: 0; }
    .topbar-course-title { font-size: 0.85rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; min-width: 0; }
    .progress-wrap { display: flex; align-items: center; gap: 0.6rem; flex-shrink: 0; }
    .progress-bar-track { width: 140px; height: 6px; background: #e5e7eb; border-radius: 50px; overflow: hidden; }
    .progress-bar-fill { height: 100%; background: linear-gradient(90deg, #059669, #10b981); border-radius: 50px; transition: width .5s ease; }
    .progress-pct { font-size: 0.78rem; font-weight: 700; color: #059669; white-space: nowrap; }
    .topbar-right { display: flex; align-items: center; gap: 0.75rem; flex-shrink: 0; }
    /* Issue 6 fix: topbar-avatar hover state */
    .topbar-avatar { width: 32px; height: 32px; background: var(--blue); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 0.85rem; font-weight: 700; cursor: pointer; transition: background .2s, transform .2s; }
    .topbar-avatar:hover { background: var(--blue-dark); transform: scale(1.08); }
    .btn-contents { display: none; align-items: center; gap: 0.4rem; background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 0.35rem 0.7rem; font-size: 0.82rem; font-weight: 600; color: var(--text); cursor: pointer; transition: all .2s; font-family: 'Inter', sans-serif; }
    .btn-contents:hover { background: var(--blue-light); color: var(--blue); }
    .topbar-cert-btn { display: none; align-items: center; gap: 0.35rem; background: linear-gradient(135deg, #f59e0b, #d97706); color: #fff; border: none; border-radius: 6px; padding: 0.35rem 0.8rem; font-size: 0.8rem; font-weight: 700; cursor: pointer; transition: all .2s; font-family: 'Inter', sans-serif; white-space: nowrap; min-height: 44px; }
    .topbar-cert-btn:hover { background: linear-gradient(135deg, #d97706, #b45309); box-shadow: 0 2px 8px rgba(245,158,11,.4); transform: translateY(-1px); }
    .topbar-cert-btn.show { display: flex; }

    /* LAYOUT */
    .player-layout { display: flex; height: 100vh; padding-top: var(--topbar-h); overflow: hidden; }

    /* SIDEBAR */
    .sidebar {
      width: var(--sidebar-w);
      flex-shrink: 0;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      border-right: 1px solid rgba(229,231,235,0.95);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      transition: transform .3s ease;
      box-shadow: 8px 0 20px rgba(2, 24, 68, 0.04);
    }
    .sidebar-header {
      padding: 1rem;
      border-bottom: 1px solid rgba(229,231,235,0.9);
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-shrink: 0;
      background: linear-gradient(135deg, #f6faff, #eef4ff);
    }
    /* Issue 11 fix: consolidated sidebar font sizes, 3 clear tiers */
    .sidebar-header h3 { font-size: 0.88rem; font-weight: 700; }
    .sidebar-header-right { display: flex; align-items: center; gap: 0.5rem; }
    .sidebar-lesson-count { font-size: 0.75rem; color: var(--text-muted); background: var(--bg); padding: 0.15rem 0.5rem; border-radius: 50px; }
    /* Issue 3 fix: btn-close-sidebar minimum 44px tap target + hover state */
    .btn-close-sidebar { display: none; background: none; border: none; cursor: pointer; color: var(--text-muted); font-size: 1.1rem; padding: 0.2rem; line-height: 1; min-width: 44px; min-height: 44px; border-radius: 6px; transition: color .2s, background .2s; }
    .btn-close-sidebar:hover { color: var(--red); background: #fee2e2; }
    .sidebar-scroll { flex: 1; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--border) transparent; }
    .sidebar-scroll::-webkit-scrollbar { width: 6px; }
    .sidebar-scroll::-webkit-scrollbar-track { background: transparent; }
    .sidebar-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
    .sidebar-module-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.78rem 1rem;
      background: #f7faff;
      cursor: pointer;
      border-bottom: 1px solid #dce7ff;
      border-left: 3px solid transparent;
      user-select: none;
      transition: all .2s;
    }
    .sidebar-module-header:hover { background: #eaf1ff; border-left-color: var(--blue); }
    .sidebar-module-header.open { background: #eaf1ff; border-left-color: var(--blue); }
    /* Issue 11 fix: sidebar module title tier-1 (0.83rem), meta tier-2 (0.76rem), chevron consistent */
    .sidebar-module-title { font-size: 0.83rem; font-weight: 700; color: var(--blue); line-height: 1.35; }
    .sidebar-module-meta { font-size: 0.76rem; color: #3a5a8c; margin-top: 0.1rem; }
    .sidebar-module-chevron { font-size: 0.76rem; color: var(--blue); transition: transform .2s; opacity: 0.7; }
    .sidebar-module-header.open .sidebar-module-chevron { transform: rotate(180deg); }
    .sidebar-lessons { display: none; }
    .sidebar-lessons.open { display: block; }
    .sidebar-lesson {
      display: flex;
      align-items: center;
      gap: 0.6rem;
      padding: 0.72rem 1rem;
      border-bottom: 1px solid #f3f4f6;
      cursor: pointer;
      transition: background .15s, transform .15s;
      border-left: 3px solid transparent;
    }
    .sidebar-lesson:hover:not(.locked) { background: #f5f8ff; transform: translateX(2px); }
    .sidebar-lesson.active { background: #eff6ff; border-left-color: var(--blue); box-shadow: inset 0 0 0 1px rgba(0,40,104,0.04); }
    .sidebar-lesson.completed { background: #f0fdf7; border-left-color: #a7f3d0; }
    .sidebar-lesson.completed .lesson-status { color: var(--green); font-weight: 700; }
    /* Locked rows stay clickable so the "complete the previous lesson first"
       toast can actually fire. They previously had pointer-events:none, which
       silently swallowed the click and left the row's own onclick handler as
       dead code — a learner tapped a padlock and nothing whatsoever happened,
       with no hint that the lock is about sequence, not payment. */
    .sidebar-lesson.locked { opacity: 0.55; cursor: not-allowed; }
    .sidebar-lesson.locked:hover { background: #fff7ed; transform: none; }
    .sidebar-lesson.locked .lesson-status { color: #9ca3af; }
    .sidebar-lesson.locked .lesson-info-title { color: #9ca3af; }
    /* Lock toast notification */
    .lock-toast { position: fixed; bottom: 5rem; left: 50%; transform: translateX(-50%) translateY(20px); background: #1e293b; color: #fff; padding: 0.7rem 1.2rem; border-radius: 8px; font-size: 0.88rem; font-weight: 500; opacity: 0; transition: opacity .3s, transform .3s; z-index: 9999; pointer-events: none; white-space: nowrap; box-shadow: 0 4px 16px rgba(0,0,0,.3); }
    .lock-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
    /* Pulse animation for Mark Complete button */
    @keyframes pulse-btn { 0%,100%{box-shadow:0 0 0 0 rgba(0,40,104,.4)} 50%{box-shadow:0 0 0 8px rgba(0,40,104,0)} }
    .pulse-cta { animation: pulse-btn 1s ease 3; }
    /* Issue 11 fix: lesson items use tier-2 (0.83rem) title and tier-3 (0.76rem) duration */
    .lesson-status { font-size: 0.83rem; flex-shrink: 0; width: 16px; text-align: center; }
    .lesson-info { flex: 1; min-width: 0; }
    .lesson-info-title { font-size: 0.83rem; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .sidebar-lesson.active .lesson-info-title { color: var(--blue); font-weight: 700; }
    .sidebar-lesson.completed .lesson-info-title { color: #065f46; }
    .lesson-info-dur { font-size: 0.76rem; color: var(--text-muted); }

    /* MAIN AREA */
    .main-area { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
    .video-scroll { flex: 1; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--border) transparent; }
    .video-scroll::-webkit-scrollbar { width: 6px; }
    .video-scroll::-webkit-scrollbar-track { background: transparent; }
    .video-scroll::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
    .video-container {
      background: linear-gradient(135deg, #020817 0%, #091a39 40%, #0a224c 100%);
      position: relative;
      /* Size the player from the height available, not just the width.
         At 16:9 across a full-width desktop pane the poster alone took ~67%
         of the viewport, so the lesson title, the tabs and every word of the
         note started below the fold — on a course where the written note is
         the part learners revise from. Deriving the width from the leftover
         height keeps the video generous while guaranteeing the note begins
         on the first screen. Mobile is unaffected: 100% still wins there. */
      width: min(100%, var(--content-w), max(420px, calc((100vh - var(--topbar-h) - 430px) * 16 / 9)));
      margin: 1rem auto 0;
      padding-top: 56.25%;
      overflow: hidden;
      border-radius: 20px;
      box-shadow: 0 14px 38px rgba(3, 16, 44, 0.18);
      border: 1px solid rgba(255,255,255,0.08);
    }
    @supports (aspect-ratio: 16/9) {
      .video-container { aspect-ratio: 16/9; padding-top: 0; }
    }
    .video-container iframe,
    .video-container #ytPlayer { position: absolute; top: 0; left: 0; right: 0; bottom: 0; width: 100%; height: 100%; border: none; z-index: 1; }
    /* Branded top bar, covers the player's title/share chrome during playback */
    .video-topbar {
      position: absolute; top: 0; left: 0; right: 0; height: 46px; z-index: 5;
      display: none; align-items: center; gap: 0.45rem; padding: 0 0.9rem;
      background: linear-gradient(180deg, rgba(11,31,58,0.99) 0%, rgba(11,31,58,0.9) 55%, rgba(11,31,58,0) 100%);
      font-family: 'Poppins', sans-serif; pointer-events: none;
    }
    .video-container.playing .video-topbar { display: flex; }
    .video-topbar .vt-brand { color: #fff; font-weight: 700; font-size: 0.78rem; letter-spacing: 0.02em; }
    .video-topbar .vt-brand span { color: #ff8a94; }
    /* Click-shield: blocks tapping any underlying player links; taps toggle play/pause */
    .video-shield { position: absolute; inset: 0; z-index: 3; display: none; cursor: pointer; background: transparent; }
    .video-container.playing .video-shield { display: block; }
    .video-container.fallback .video-shield { display: none; }
    /* Auto-hide the brand strip + controls while watching so the video (and any
       on-screen text in it) is never covered; a tap brings them back. */
    .video-container.playing .video-topbar,
    .video-container.playing .video-controls { transition: opacity .3s ease; }
    .video-container.playing.chrome-hidden .video-topbar,
    .video-container.playing.chrome-hidden .video-controls { opacity: 0; pointer-events: none; }
    /* Custom TIH control bar */
    .video-controls {
      position: absolute; left: 0; right: 0; bottom: 0; z-index: 6;
      display: none; align-items: center; gap: 0.5rem; padding: 0.45rem 0.7rem 0.55rem;
      background: linear-gradient(0deg, rgba(11,31,58,0.94) 0%, rgba(11,31,58,0.55) 70%, transparent 100%);
    }
    .video-container.playing .video-controls { display: flex; }
    .video-container.fallback .video-controls { display: none; }
    .video-controls .vc-btn { background: none; border: none; color: #fff; font-size: 1rem; line-height: 1; cursor: pointer; padding: 0.2rem 0.25rem; display: flex; }
    .video-controls .vc-seek { flex: 1; -webkit-appearance: none; appearance: none; height: 4px; border-radius: 4px; background: rgba(255,255,255,0.3); cursor: pointer; }
    .video-controls .vc-seek::-webkit-slider-thumb { -webkit-appearance: none; width: 13px; height: 13px; border-radius: 50%; background: #E31E24; cursor: pointer; }
    .video-controls .vc-seek::-moz-range-thumb { width: 13px; height: 13px; border: 0; border-radius: 50%; background: #E31E24; cursor: pointer; }
    .video-controls .vc-time { color: #fff; font-size: 0.72rem; font-variant-numeric: tabular-nums; white-space: nowrap; }
    /* Custom click-to-play poster, no third-party branding is shown before play */
    .video-poster {
      position: absolute; inset: 0; z-index: 8; cursor: pointer;
      display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.85rem;
      text-align: center; padding: 1rem;
      background:
        radial-gradient(circle at 50% 30%, rgba(56,132,255,0.65), transparent 66%),
        linear-gradient(135deg, #2f6fe0 0%, #1553b8 45%, #0a337e 100%);
    }
    .video-container.playing .video-poster { display: none; }
    .video-poster .vp-play {
      width: 82px; height: 82px; border-radius: 50%;
      background: #fff; border: none;
      display: flex; align-items: center; justify-content: center;
      transition: transform 0.2s, background 0.2s, box-shadow 0.2s;
      box-shadow: 0 10px 30px rgba(0,0,0,0.32);
    }
    .video-poster:hover .vp-play, .video-poster:active .vp-play { transform: scale(1.09); box-shadow: 0 14px 38px rgba(227,30,36,0.5); }
    .video-poster .vp-play svg { width: 32px; height: 32px; fill: #E31E24; margin-left: 5px; }
    .video-poster .vp-title { color: #fff; font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 1rem; line-height: 1.35; max-width: 88%; text-shadow: 0 1px 6px rgba(0,0,0,0.28); }
    .video-poster .vp-hint { color: #fff; font-size: 0.82rem; font-weight: 600; display: inline-flex; align-items: center; gap: 0.35rem; background: rgba(255,255,255,0.18); padding: 0.3rem 0.8rem; border-radius: 999px; }
    .video-info-bar {
      padding: 1rem 1.5rem 0.9rem;
      border-bottom: 1px solid rgba(229,231,235,0.9);
      background: rgba(255,255,255,0.82);
      backdrop-filter: blur(8px);
      margin: 0.9rem auto 0;
      width: min(100%, var(--content-w));
      /* Title, tabs and note are one card, not three floating panels. */
      border-radius: 18px 18px 0 0;
      box-shadow: 0 10px 24px rgba(2, 24, 68, 0.05);
    }
    .video-lesson-title { font-size: 1.12rem; font-weight: 700; margin-bottom: 0.25rem; font-family: 'Poppins', sans-serif; color: #111827; line-height: 1.35; }
    .video-lesson-meta { display: flex; align-items: center; gap: 0.85rem; font-size: 0.8rem; color: var(--text-muted); flex-wrap: wrap; }
    .video-lesson-meta span { display: flex; align-items: center; gap: 0.3rem; }

    /* TABS */
    .tabs-bar {
      display: flex;
      border-bottom: 2px solid #f1f5f9;
      padding: 0 1rem;
      background: rgba(255,255,255,0.78);
      backdrop-filter: blur(8px);
      width: min(100%, var(--content-w));
      margin: 0 auto;
      border-radius: 0;
      box-shadow: none;
    }
    .tab-btn { padding: 0.75rem 0.9rem; border: none; background: none; font-size: 0.84rem; font-weight: 600; color: var(--text-muted); cursor: pointer; border-bottom: 2.5px solid transparent; margin-bottom: -2px; transition: all .18s; font-family: 'Inter', sans-serif; min-height: 44px; }
    .tab-btn:hover { color: var(--blue); }
    .tab-btn.active { color: var(--blue); border-bottom-color: var(--blue); background: linear-gradient(180deg, transparent 70%, #eff6ff 100%); }
    .tab-panel {
      display: none;
      padding: 1.25rem 1.35rem;
      width: min(100%, var(--content-w));
      margin: 0 auto;
      background: rgba(255,255,255,0.92);
      border-radius: 0 0 18px 18px;
      box-shadow: 0 10px 24px rgba(2, 24, 68, 0.05);
    }
    .tab-panel.active { display: block; }
    .overview-text p { font-size: 0.95rem; color: #374151; line-height: 1.75; margin-bottom: 0.95rem; }
    .overview-text p:last-child { margin-bottom: 0; }
    .overview-text { max-width: 100%; }
    /* Hold prose to a comfortable measure. Full-width lines ran past 110
       characters, well beyond the 45-75 that reading research supports and
       harder still for learners studying in a second language. Tables,
       diagrams and code keep the wider container so they are not squeezed. */
    .overview-text > p,
    .overview-text li,
    .overview-text > blockquote,
    .overview-text .lesson-note-intro,
    .overview-text .lesson-note-section > p,
    .overview-text .lesson-note-example,
    .overview-text .lesson-note-action { max-width: 68ch; }
    .overview-text .lesson-note-intro { background: linear-gradient(135deg,#eff6ff,#f8fbff); border: 1px solid #cfe0f7; border-left: 4px solid var(--blue); border-radius: 12px; padding: 1rem 1.1rem; margin-bottom: 1.2rem; color: #183b6c; }
    .overview-text .lesson-note-section { margin-top: 1.25rem; padding-top: 1rem; border-top: 1px solid #e5edf8; }
    .overview-text .lesson-note-section h4 { margin-top: 0; }
    .overview-text .lesson-note-checklist { display: grid; gap: .45rem; margin: .5rem 0 1rem 0; padding: 0; list-style: none; }
    .overview-text .lesson-note-checklist li { padding: .55rem .7rem .55rem 2rem; background: #f8fbff; border: 1px solid #e2ebf7; border-radius: 8px; position: relative; }
    .overview-text .lesson-note-checklist li::before { content: '✓'; position: absolute; left: .7rem; color: var(--green); font-weight: 800; }
    .overview-text .lesson-note-example { background: #fffaf0; border: 1px solid #f7dca0; border-radius: 10px; padding: .85rem 1rem; }
    .overview-text .lesson-note-action { background: #f0fdf7; border: 1px solid #b7ead2; border-radius: 10px; padding: .85rem 1rem; }
    .overview-text .wassce-note { max-width: 900px; color: #26364d; font-family: Georgia, 'Times New Roman', serif; font-size: 1.04rem; line-height: 1.9; letter-spacing: .005em; }
    .overview-text .wassce-note .lesson-note-intro,
    .overview-text .wassce-note .lesson-note-action,
    .overview-text .wassce-note .lesson-note-section { font-family: Georgia, 'Times New Roman', serif; }
    .overview-text .wassce-note .wassce-note-header { padding: 1.35rem 1.45rem; margin-bottom: 1.45rem; border-radius: 14px; background: linear-gradient(135deg, #eff6ff, #ffffff 72%); border: 1px solid #cfe0f7; border-left: 5px solid #002868; }
    .overview-text .wassce-note .wassce-note-kicker { display: block; margin-bottom: .35rem; color: #b45309; font-family: Inter, sans-serif; font-size: .72rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
    .overview-text .wassce-note .wassce-note-header h3 { margin: 0 0 .55rem; color: #002868; font-family: Poppins, sans-serif; font-size: clamp(1.35rem, 2.5vw, 1.85rem); line-height: 1.25; }
    .overview-text .wassce-note .wassce-note-header p { margin: 0; color: #3c506b; font-size: 1rem; line-height: 1.8; }
    .overview-text .wassce-note .wassce-note-section { margin: 1.6rem 0 0; padding: 1.15rem 1.25rem; border-top: 1px solid #dbe7f5; }
    .overview-text .wassce-note .wassce-note-section h4 { margin: 0 0 .7rem; color: #002868; font-family: Poppins, sans-serif; font-size: 1.08rem; line-height: 1.4; }
    .overview-text .wassce-note .wassce-note-section p { color: #26364d; font-size: 1.02rem; line-height: 1.9; margin-bottom: 1rem; }
    .overview-text .wassce-note .wassce-note-section p:last-child { margin-bottom: 0; }
    .overview-text .wassce-note .wassce-note-section ul,
    .overview-text .wassce-note .wassce-note-section ol { margin: .55rem 0 .25rem 1.45rem; padding-left: .6rem; }
    .overview-text .wassce-note .wassce-note-section li { margin-bottom: .55rem; color: #26364d; font-size: 1rem; line-height: 1.8; }
    .overview-text .wassce-note .wassce-note-section strong { color: #173f75; }
    .overview-text .wassce-note .wassce-study-plan { background: #f8fbff; border: 1px solid #dce9f8; border-radius: 12px; }
    .overview-text .wassce-note .wassce-revision-box { background: #fffbeb; border: 1px solid #f3df9b; border-radius: 12px; }
    .overview-text .wassce-note sub, .overview-text .wassce-note sup { line-height: 0; }
    .overview-text .wassce-note h4 + p { margin-top: .1rem; }
    .overview-text .wassce-note .wassce-table-wrap { width: 100%; overflow-x: auto; margin: 1rem 0 1.25rem; border: 1px solid #cfe0f7; border-radius: 12px; background: #fff; box-shadow: 0 5px 16px rgba(2,24,68,.06); -webkit-overflow-scrolling: touch; }
    .overview-text .wassce-note table { width: 100%; min-width: 560px; border-collapse: separate; border-spacing: 0; font-family: Inter, sans-serif; font-size: .9rem; line-height: 1.55; }
