    }
    .video-unavailable { min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 2rem; color: rgba(255,255,255,.8); background: radial-gradient(circle at 50% 25%, rgba(21,101,216,.35), transparent 55%), linear-gradient(135deg,#0b1f3a,#002868); }
    .video-unavailable .vu-icon { font-size: 2.6rem; margin-bottom: .7rem; }
    .video-unavailable strong { color: #fff; font-family: 'Poppins',sans-serif; font-size: 1rem; }
    .video-unavailable p { max-width: 470px; margin-top: .45rem; font-size: .82rem; line-height: 1.6; color: rgba(255,255,255,.7); }
    .overview-text h4 { font-size: 0.92rem; font-weight: 700; color: var(--blue); margin: 1.1rem 0 0.35rem; }
    .overview-text ul { margin: 0.3rem 0 0.9rem 1.3rem; }
    .overview-text li { font-size: 0.88rem; color: #374151; line-height: 1.75; margin-bottom: 0.3rem; }
    .resource-item { display: flex; align-items: center; gap: 0.75rem; padding: 0.9rem 1rem; border: 1px solid var(--border); border-radius: 10px; margin-bottom: 0.6rem; transition: all .2s; }
    .resource-item:hover { border-color: var(--blue); background: var(--blue-light); }
    .resource-icon { font-size: 1.5rem; flex-shrink: 0; }
    .resource-info { flex: 1; }
    .resource-name { font-size: 0.88rem; font-weight: 600; }
    .resource-size { font-size: 0.77rem; color: var(--text-muted); }
    /* Issue 5 fix: btn-download minimum 44px tap target */
    .btn-download { background: var(--blue); color: #fff; border: none; padding: 0.4rem 0.9rem; border-radius: 6px; font-size: 0.8rem; font-weight: 600; cursor: pointer; transition: all .2s; font-family: 'Inter', sans-serif; min-height: 44px; display: inline-flex; align-items: center; }
    .btn-download:hover { background: var(--blue-dark); }
    .qa-item { border: 1px solid var(--border); border-radius: 10px; padding: 1rem; margin-bottom: 0.75rem; }
    .qa-question { font-size: 0.88rem; font-weight: 600; margin-bottom: 0.5rem; display: flex; gap: 0.5rem; }
    .qa-question::before { content: 'Q:'; color: var(--blue); flex-shrink: 0; }
    .qa-answer { font-size: 0.87rem; color: #374151; line-height: 1.75; display: flex; gap: 0.5rem; }
    .qa-answer::before { content: 'A:'; color: var(--green); font-weight: 700; flex-shrink: 0; }
    .notes-label { font-size: 0.85rem; font-weight: 600; margin-bottom: 0.35rem; color: var(--blue); }
    .notes-prompt { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 0.6rem; font-style: italic; }
    .notes-textarea { width: 100%; min-height: 160px; padding: 0.75rem 1rem; border: 1.5px solid var(--border); border-radius: 8px; font-size: 0.88rem; font-family: 'Inter', sans-serif; resize: vertical; transition: border-color .2s; line-height: 1.7; }
    .notes-textarea:focus { outline: none; border-color: var(--blue); }
    .notes-actions { display: flex; align-items: center; gap: 0.6rem; margin-top: 0.75rem; flex-wrap: wrap; }
    .btn-save-notes { background: var(--blue); color: #fff; border: none; padding: 0.5rem 1.2rem; border-radius: 8px; font-size: 0.82rem; font-weight: 600; cursor: pointer; transition: all .2s; font-family: 'Inter', sans-serif; min-height: 44px; }
    .btn-save-notes:hover { background: var(--blue-dark); }
    .btn-all-notes { background: #fff; color: var(--blue); border: 1.5px solid var(--blue); padding: 0.5rem 1rem; border-radius: 8px; font-size: 0.82rem; font-weight: 600; cursor: pointer; font-family: 'Inter', sans-serif; transition: all .2s; min-height: 44px; }
    .btn-all-notes:hover { background: var(--blue-light); }
    .btn-export-notes { background: #fff; color: #374151; border: 1.5px solid var(--border); padding: 0.5rem 1rem; border-radius: 8px; font-size: 0.82rem; font-weight: 600; cursor: pointer; font-family: 'Inter', sans-serif; transition: all .2s; min-height: 44px; }
    .btn-export-notes:hover { border-color: #6b7280; }
    .notes-saved-msg { font-size: 0.82rem; color: var(--green); font-weight: 500; opacity: 0; transition: opacity .3s; }
    .notes-saved-msg.show { opacity: 1; }
    .note-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--gold); margin-left: 5px; flex-shrink: 0; vertical-align: middle; }
    /* All Notes Modal */
    .all-notes-panel { background: #fff; border-radius: 16px; width: min(680px, 95vw); max-height: 85vh; display: flex; flex-direction: column; overflow: hidden; }
    .all-notes-header { display: flex; align-items: center; justify-content: space-between; padding: 1rem 1.25rem; border-bottom: 1px solid var(--border); flex-shrink: 0; }
    .all-notes-title { font-size: 1.05rem; font-weight: 700; color: var(--blue); }
    .all-notes-header-btns { display: flex; align-items: center; gap: 0.5rem; }
    .all-notes-content { overflow-y: auto; padding: 1rem 1.25rem; flex: 1; }
    .note-entry { border: 1px solid var(--border); border-radius: 10px; margin-bottom: 1rem; overflow: hidden; }
    .note-entry-header { background: var(--bg-alt); padding: 0.6rem 1rem; display: flex; align-items: center; justify-content: space-between; }
    .note-entry-title { font-size: 0.85rem; font-weight: 600; color: var(--blue); }
    .note-entry-meta { font-size: 0.75rem; color: var(--text-muted); }
    .note-entry-body { padding: 0.75rem 1rem; font-size: 0.87rem; line-height: 1.7; color: #374151; white-space: pre-wrap; word-break: break-word; }
    .all-notes-empty { text-align: center; padding: 2.5rem 1rem; color: var(--text-muted); }
    .all-notes-empty p { margin-top: 0.5rem; font-size: 0.9rem; }

    /* LESSON NAV BAR */
    .lesson-nav-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.9rem 1.5rem;
      border-top: 1px solid rgba(229,231,235,0.95);
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(8px);
      flex-wrap: nowrap;
      gap: 0.5rem;
      flex-shrink: 0;
      width: min(100%, var(--content-w));
      margin: 0.9rem auto 0;
      border-radius: 16px;
      box-shadow: 0 10px 24px rgba(2, 24, 68, 0.05);
    }
    .btn-mark-complete { background: linear-gradient(135deg, #002868, #0040a8); color: #fff; border: none; padding: 0.55rem 1.1rem; border-radius: 10px; font-size: 0.84rem; font-weight: 700; cursor: pointer; transition: all .2s; font-family: 'Inter', sans-serif; display: flex; align-items: center; gap: 0.35rem; white-space: nowrap; box-shadow: 0 4px 10px rgba(0,40,104,.25); flex-shrink: 0; min-height: 44px; }
    .btn-mark-complete:hover { background: linear-gradient(135deg, #001a45, #002868); box-shadow: 0 4px 12px rgba(0,40,104,.35); }
    .btn-mark-complete.done { background: linear-gradient(135deg, #059669, #10b981); box-shadow: 0 2px 8px rgba(16,185,129,.3); cursor: default; }
    /* The dot strip is per-module and modules run as long as 39 lessons, so it
       has to be allowed to shrink -- at flex-shrink:0 it shoved the Next button
       off the end of the bar. updateProgressDots() also windows the dots. */
    .lesson-progress-dots { display: flex; align-items: center; gap: 4px; flex-shrink: 1; min-width: 0; overflow: hidden; justify-content: center; }
    .dots-count { font-size: 0.72rem; font-weight: 700; color: var(--text-muted); white-space: nowrap; margin-left: 0.35rem; flex-shrink: 0; font-variant-numeric: tabular-nums; }
    /* Issue 7 fix: progress-dot hover state */
    .progress-dot { width: 8px; height: 8px; border-radius: 50%; background: #e5e7eb; transition: all .25s; cursor: default; }
    .progress-dot:hover { background: #9ca3af; transform: scale(1.4); }
    .progress-dot.done { background: var(--green); }
    .progress-dot.done:hover { background: #059669; }
    .progress-dot.active { background: var(--blue); width: 22px; border-radius: 4px; }
    .progress-dot.active:hover { background: var(--blue-dark); }
    /* These were written as `.btn-next-lesson.btn-prev-lesson` -- a compound
       selector matching an element carrying BOTH classes, which no button does.
       Prev and Next therefore rendered as raw grey browser buttons with a black
       border, 34px tall (under the 44px touch target) on every lesson. */
    .btn-prev-lesson,
    .btn-next-lesson {
      display: flex; align-items: center; gap: 0.5rem;
      background: #fff; color: var(--blue); border: 1.5px solid #bfdbfe;
      padding: 0.4rem 0.85rem; border-radius: 12px;
      font-family: 'Inter', sans-serif; cursor: pointer; transition: all .2s;
      flex: 0 1 clamp(112px, 27%, 250px); min-width: 0; min-height: 44px;
      text-align: left;
    }
    .btn-next-lesson { justify-content: flex-end; text-align: right; }
    /* Two-line label: the direction stays readable however long the lesson title
       is, and the title ellipses in CSS instead of being cut at 22 characters. */
    .nav-label { display: flex; flex-direction: column; min-width: 0; line-height: 1.25; }
    .nav-dir { font-size: 0.64rem; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--text-muted); transition: color .2s; }
    .nav-title { font-size: 0.82rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .nav-arrow { font-size: 1.2rem; line-height: 1; flex-shrink: 0; }
    .btn-prev-lesson:hover:not(:disabled) { background: #eff6ff; border-color: #93c5fd; }
    .btn-next-lesson:hover:not(:disabled) { background: var(--blue); color: #fff; border-color: var(--blue); }
    .btn-next-lesson:hover:not(:disabled) .nav-dir { color: rgba(255,255,255,.8); }
    .btn-prev-lesson:disabled,
    .btn-next-lesson:disabled { opacity: 0.45; cursor: default; border-color: var(--border); color: var(--text-muted); background: #fff; }
    .btn-prev-lesson:focus-visible,
    .btn-next-lesson:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }

    /* QUIZ MODAL */
    .modal-overlay { display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,.6); z-index: 9000; align-items: center; justify-content: center; padding: 1rem; }
    .modal-overlay.open { display: flex; }
    .quiz-modal { background: #fff; border-radius: 16px; padding: 2rem; max-width: 540px; width: 100%; box-shadow: 0 20px 60px rgba(0,0,0,.3); max-height: 90vh; overflow-y: auto; }
    .modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }
    .modal-title { font-size: 1.1rem; font-weight: 700; font-family: 'Poppins', sans-serif; }
    /* Issue 4 fix: btn-close-modal minimum 44px tap target */
    .btn-close-modal { background: none; border: none; cursor: pointer; color: var(--text-muted); font-size: 1.4rem; line-height: 1; padding: 0.2rem; transition: color .2s, background .2s; min-width: 44px; min-height: 44px; border-radius: 6px; display: flex; align-items: center; justify-content: center; }
    .btn-close-modal:hover { color: var(--red); background: #fee2e2; }
    .quiz-prog-wrap { height: 6px; background: var(--border); border-radius: 50px; margin-bottom: 1.25rem; overflow: hidden; }
    .quiz-prog-bar { height: 100%; background: linear-gradient(90deg, var(--blue), var(--green)); border-radius: 50px; transition: width .4s ease; }
    .quiz-question-num { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 0.4rem; }
    .quiz-question-text { font-size: 1rem; font-weight: 600; margin-bottom: 1.25rem; line-height: 1.5; }
    .quiz-options { display: flex; flex-direction: column; gap: 0.6rem; margin-bottom: 1.25rem; }
    .quiz-option { display: flex; align-items: center; gap: 0.75rem; padding: 0.75rem 1rem; border: 1.5px solid var(--border); border-radius: 10px; cursor: pointer; transition: all .2s; font-size: 0.9rem; }
    .quiz-option:hover:not(.locked-opt) { border-color: var(--blue); background: var(--blue-light); }
    .quiz-option.selected { border-color: var(--blue); background: var(--blue-light); }
    .quiz-option.correct { border-color: var(--green); background: var(--green-light); color: #065f46; }
    .quiz-option.wrong { border-color: var(--red); background: #fee2e2; color: #991b1b; }
    .quiz-option-letter { width: 28px; height: 28px; border-radius: 50%; background: var(--border); display: flex; align-items: center; justify-content: center; font-size: 0.78rem; font-weight: 700; flex-shrink: 0; transition: all .2s; }
    .quiz-option.selected .quiz-option-letter { background: var(--blue); color: #fff; }
    .quiz-option.correct .quiz-option-letter { background: var(--green); color: #fff; }
    .quiz-option.wrong .quiz-option-letter { background: var(--red); color: #fff; }
    .quiz-feedback { font-size: 0.88rem; padding: 0.75rem 1rem; border-radius: 8px; margin-bottom: 1rem; display: none; line-height: 1.6; }
    .quiz-feedback.show-correct { background: var(--green-light); color: #065f46; display: block; }
    .quiz-feedback.show-wrong { background: #fee2e2; color: #991b1b; display: block; }
    .btn-quiz-action { display: block; width: 100%; padding: 0.8rem; background: var(--blue); color: #fff; border: none; border-radius: 10px; font-size: 0.95rem; font-weight: 700; cursor: pointer; transition: all .2s; font-family: 'Poppins', sans-serif; }
    .btn-quiz-action:hover { background: var(--blue-dark); }
    .btn-quiz-action:disabled { background: var(--border); color: var(--text-muted); cursor: not-allowed; }
    .quiz-result { text-align: center; padding: 0.5rem 0 1rem; }
    .quiz-result-icon { font-size: 4rem; margin-bottom: 0.75rem; }
    .quiz-result-title { font-size: 1.4rem; font-weight: 800; margin-bottom: 0.5rem; font-family: 'Poppins', sans-serif; }
    .quiz-result-title.pass { color: var(--green); }
    .quiz-result-title.fail { color: var(--red); }
    .quiz-result-score { font-size: 3rem; font-weight: 800; color: var(--blue); line-height: 1; }
    .quiz-result-score-sub { font-size: 0.88rem; color: var(--text-muted); margin-bottom: 1.25rem; }
    .quiz-result-msg { font-size: 0.9rem; color: #374151; line-height: 1.7; margin-bottom: 1.5rem; padding: 0.9rem 1rem; background: var(--bg); border-radius: 10px; text-align: left; }

    /* COMPLETION MODAL */
    .completion-modal { background: #fff; border-radius: 20px; max-width: 560px; width: 100%; max-height: 94vh; overflow-y: auto; box-shadow: 0 32px 100px rgba(0,0,0,.5); }
    .completion-header { background: linear-gradient(150deg, #001535 0%, #002868 60%, #003580 100%); padding: 2rem 2rem 1.5rem; text-align: center; color: #fff; border-radius: 20px 20px 0 0; position: relative; overflow: hidden; }
    .completion-header::before { content: ''; position: absolute; top: -40px; left: 50%; transform: translateX(-50%); width: 220px; height: 220px; background: radial-gradient(circle, rgba(245,158,11,.22) 0%, transparent 70%); pointer-events: none; }
    .completion-header::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 3px; background: linear-gradient(90deg, transparent, #f59e0b 30%, #f59e0b 70%, transparent); }
    .completion-icon { font-size: 3.5rem; margin-bottom: 0.5rem; position: relative; z-index: 1; filter: drop-shadow(0 4px 12px rgba(245,158,11,.5)); }
    .completion-header h2 { font-size: 1.65rem; font-weight: 800; margin-bottom: 0.3rem; font-family: 'Poppins', sans-serif; position: relative; z-index: 1; }
    .completion-header p { color: rgba(255,255,255,.82); font-size: 0.9rem; position: relative; z-index: 1; }
    /* ---- CERTIFICATE ---- */
    .certificate-preview { margin: 1.25rem 1.25rem 0; border: 2.5px solid #c8960c; border-radius: 10px; padding: 0; background: linear-gradient(160deg, #fffef7 0%, #fffceb 100%); overflow: hidden; box-shadow: inset 0 0 0 4px rgba(200,150,12,.12); }
    .cert-header-band { background: linear-gradient(135deg, #001a45, #002868); padding: 0.85rem 1.25rem; display: flex; align-items: center; justify-content: center; gap: 0.7rem; }
    .cert-header-icon { font-size: 1.6rem; filter: drop-shadow(0 2px 6px rgba(245,158,11,.4)); }
    .cert-header-text { text-align: left; }
    .cert-logo { font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.1rem; color: #fff; line-height: 1.2; }
    .cert-logo span { color: #f59e0b; }
    .cert-subtitle { font-size: 0.62rem; text-transform: uppercase; letter-spacing: 0.16em; color: rgba(255,255,255,.75); margin-top: 0.1rem; }
    .cert-body { text-align: center; padding: 1rem 1.25rem 0.5rem; }
    .cert-divider { display: flex; align-items: center; gap: 0.5rem; margin: 0.55rem 0; color: #c8960c; font-size: 0.62rem; letter-spacing: 0.1em; }
    .cert-divider::before.cert-divider::after { content: ''; flex: 1; height: 1px; background: linear-gradient(90deg, transparent, #c8960c 40%, #c8960c 60%, transparent); }
    .cert-awarded { font-size: 0.82rem; color: #6b7280; margin-bottom: 0.15rem; font-style: italic; }
    .cert-name { font-family: 'Poppins', sans-serif; font-size: 1.55rem; font-weight: 700; color: #002868; display: block; margin-bottom: 0.5rem; line-height: 1.2; }
    .cert-for { font-size: 0.82rem; color: #6b7280; margin-bottom: 0.2rem; }
    .cert-course-title { font-size: 0.92rem; font-weight: 700; color: #111827; margin-bottom: 0.45rem; line-height: 1.4; }
    /* Issue 10 fix: cert date remains for date display */
    .cert-date { font-size: 0.72rem; color: #6b7280; margin-bottom: 0.35rem; }
    /* Issue 10 fix: cert ID displayed prominently */
    .cert-credential-id { display: inline-block; background: #002868; color: #f59e0b; font-family: 'Poppins', sans-serif; font-size: 0.82rem; font-weight: 800; letter-spacing: 0.08em; padding: 0.3rem 0.75rem; border-radius: 6px; margin-top: 0.35rem; }
    .cert-footer-row { display: flex; align-items: center; justify-content: space-between; padding: 0.7rem 1.25rem 0.9rem; border-top: 1px solid rgba(200,150,12,.25); margin-top: 0.5rem; }
    .cert-sig-line { width: 85px; border-bottom: 1.5px solid #374151; margin-bottom: 0.2rem; }
    .cert-sig-name { font-size: 0.72rem; font-weight: 700; color: #111827; }
    .cert-sig-role { font-size: 0.72rem; color: #6b7280; }
    .cert-verified { width: 52px; height: 52px; border-radius: 50%; background: linear-gradient(135deg, #059669, #10b981); color: #fff; display: flex; flex-direction: column; align-items: center; justify-content: center; border: 2.5px solid #fff; box-shadow: 0 3px 12px rgba(16,185,129,.4); font-size: 0.62rem; font-weight: 700; letter-spacing: 0.06em; text-align: center; line-height: 1.3; flex-shrink: 0; }
    .cert-verified-check { font-size: 1.15rem; display: block; line-height: 1; margin-bottom: 2px; }
    /* ---- ACTIONS ---- */
    .completion-actions { padding: 1rem 1.25rem 0.5rem; display: flex; flex-direction: column; gap: 0.6rem; }
    .btn-cert-primary { background: linear-gradient(135deg, #002868, #0040a8); color: #fff; border: none; padding: 0.85rem; border-radius: 10px; font-size: 0.92rem; font-weight: 700; cursor: pointer; width: 100%; font-family: 'Poppins', sans-serif; transition: all .2s; letter-spacing: 0.01em; box-shadow: 0 4px 14px rgba(0,40,104,.3); }
    .btn-cert-primary:hover { background: linear-gradient(135deg, #001a45, #002868); box-shadow: 0 6px 20px rgba(0,40,104,.4); }
    .cert-row { display: flex; gap: 0.6rem; }
    .btn-cert-sec { flex: 1; background: #f9fafb; border: 1.5px solid #e5e7eb; padding: 0.65rem 0.5rem; border-radius: 10px; font-size: 0.82rem; font-weight: 600; cursor: pointer; font-family: 'Inter', sans-serif; transition: all .2s; color: #374151; text-align: center; text-decoration: none; display: flex; align-items: center; justify-content: center; gap: 0.3rem; min-height: 44px; }
    .btn-cert-sec:hover { border-color: var(--blue); color: var(--blue); background: #eff6ff; }
    .btn-close-completion { display: block; margin: 0.6rem 1.25rem 1.25rem; padding: 0.55rem; border: 1.5px solid #e5e7eb; background: transparent; border-radius: 10px; color: #6b7280; font-size: 0.82rem; cursor: pointer; width: calc(100% - 2.5rem); font-family: 'Inter', sans-serif; transition: all .2s; }
    .btn-close-completion:hover { border-color: var(--red); color: var(--red); background: #fff1f2; }
    /* Issue 15 fix: cert-name-row as CSS class instead of inline styles */
    .cert-name-row { margin: 0.75rem 0 0.25rem; text-align: center; padding: 0 1.25rem; }
    .cert-name-row label { display: block; font-size: 0.82rem; color: #6b7280; font-weight: 500; margin-bottom: 0.4rem; }
    .cert-name-row input { border: 1.5px solid #d1d5db; border-radius: 8px; padding: 0.45rem 0.9rem; font-size: 0.97rem; width: 100%; max-width: 320px; outline: none; text-align: center; font-family: inherit; transition: border-color .2s, box-shadow .2s; }
    .cert-name-row input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(0,40,104,.12); }

    /* SIDEBAR OVERLAY (mobile) */
    .sidebar-overlay { display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,.5); z-index: 998; }
    .sidebar-overlay.open { display: block; }

    /* CONFETTI */
    #confettiCanvas { position: fixed; top: 0; left: 0; right: 0; bottom: 0; pointer-events: none; z-index: 10001; display: none; }

    /* MOBILE */
    @media(max-width: 768px) {
      .sidebar { position: fixed; top: var(--topbar-h); left: 0; bottom: 0; z-index: 999; transform: translateX(-100%); }
      .sidebar.open { transform: translateX(0); }
      .btn-close-sidebar { display: block; }
      .btn-contents { display: flex; }
      .topbar-course-title { display: none; }
      /* Issue 14 fix: show compact progress on mobile instead of hiding it entirely */
      .progress-wrap { display: flex; }
      .progress-bar-track { width: 80px; }
      .progress-pct { font-size: 0.72rem; }
      .tabs-bar { overflow-x: auto; }
      .tab-btn { white-space: nowrap; }
      /* Issue 7 fix: stack the lesson nav from tablet width down so the
         Prev / dots / Mark-Complete / Next controls are no longer cramped on
         481-768px screens (previously only stacked at <=480px).
         A straight column put five full-width controls in a 245px-tall block on
         a 390px phone. Grid instead: the action the learner came for sits on
         top, Prev and Next share one row, and the dot strip closes it out --
         same controls, about 100px less scrolling. */
      .lesson-nav-bar { display: grid; grid-template-columns: 1fr 1fr; align-items: stretch; padding: 0.75rem 1rem; gap: 0.5rem; }
      .btn-mark-complete { grid-column: 1 / -1; order: 1; }
      #tihQuickQuizBtn { grid-column: 1 / -1; order: 2; }
      .btn-prev-lesson { order: 3; }
      .btn-next-lesson { order: 4; }
      .lesson-progress-dots { grid-column: 1 / -1; order: 5; }
      .btn-mark-complete, .btn-next-lesson, .btn-prev-lesson { justify-content: center; max-width: 100%; }
      .btn-next-lesson, .btn-prev-lesson { overflow: hidden; padding: 0.4rem 0.6rem; gap: 0.3rem; }
      .btn-next-lesson { text-align: center; }
      /* width:100% keeps the label inside the button so .nav-title can actually
         ellipse -- shrink-to-fit lets a long title spill past the border. */
      .nav-label { align-items: center; width: 100%; }
      .nav-title { width: 100%; text-align: center; }
      .lesson-progress-dots { justify-content: center; }
    }
    @media(max-width: 480px) {
      .topbar { padding: 0 0.75rem; gap: 0.6rem; }
      .topbar-back span { display: none; }
      .video-info-bar { padding: 0.75rem 1rem 0.6rem; }
      .video-lesson-title { font-size: 1rem; }
      .tab-panel { padding: 1rem; }
    }

    /* ===================================================================
       REFINEMENT LAYER — professional polish.
       Appended last so it overrides the rules above without editing them,
       which keeps every existing selector and its behaviour intact.
       Principles: one elevation scale instead of ad-hoc shadows, calmer
       surfaces (hairline borders rather than competing gradients), a real
       type hierarchy, and visible focus for keyboard users.
       =================================================================== */
    :root {
      /* Layered elevation — two shadows per level (contact + ambient) reads
         far more like real depth than a single large blur. */
      --e1: 0 1px 2px rgba(2,24,68,.06), 0 1px 3px rgba(2,24,68,.04);
      --e2: 0 2px 4px rgba(2,24,68,.05), 0 4px 12px rgba(2,24,68,.06);
      --e3: 0 4px 8px rgba(2,24,68,.05), 0 12px 28px rgba(2,24,68,.08);
      --r-sm: 8px; --r-md: 12px; --r-lg: 16px;
      --ring: 0 0 0 3px rgba(21,101,216,.28);
      --ease: cubic-bezier(.4,0,.2,1);
      --surface: #ffffff;
      --hairline: #e8edf5;
    }

    body {
      background: linear-gradient(180deg, #fafcff 0%, #f4f7fc 100%);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      font-feature-settings: 'kern' 1, 'liga' 1;
    }

    /* --- Top bar: solid, quiet, one hairline --- */
    .topbar {
      background: var(--surface);
      border-bottom: 1px solid var(--hairline);
      box-shadow: var(--e1);
      backdrop-filter: none;
    }
    .topbar-brand { letter-spacing: -.02em; }
    .topbar-course-title { color: #33415c; letter-spacing: -.01em; }
    .progress-bar-track { background: #e8edf5; height: 5px; }
    .progress-bar-fill { background: linear-gradient(90deg, #059669, #34d399); }

    /* --- Sidebar: flat surface, clear structure --- */
    .sidebar {
      background: var(--surface);
      border-right: 1px solid var(--hairline);
      box-shadow: none;
    }
    .sidebar-header {
      background: var(--surface);
      border-bottom: 1px solid var(--hairline);
      padding: 1rem 1.1rem;
    }
    .sidebar-header h3 {
      letter-spacing: .04em;
      text-transform: uppercase;
      font-size: .72rem;
      color: var(--text-muted);
      font-weight: 700;
    }
    .sidebar-lesson-count {
      background: #f1f5fb; color: #45577a; font-weight: 600;
      font-size: .72rem; border-radius: 999px;
    }
    .sidebar-scroll::-webkit-scrollbar { width: 8px; }
    .sidebar-scroll::-webkit-scrollbar-thumb {
      background: #d6dfec; border-radius: 999px;
      border: 2px solid var(--surface);   /* inset look */
    }
    .sidebar-scroll::-webkit-scrollbar-thumb:hover { background: #bccbdf; }

    /* Module headers read as section dividers, not buttons competing with lessons */
    .sidebar-module-header {
      background: #f8fafd;
      border-bottom: 1px solid var(--hairline);
      border-left: 3px solid transparent;
      padding: .8rem 1.1rem;
      transition: background .18s var(--ease), border-color .18s var(--ease);
    }
    .sidebar-module-header:hover,
    .sidebar-module-header.open { background: #eef3fb; border-left-color: var(--blue); }
    .sidebar-module-title { letter-spacing: -.01em; color: #12294f; }
    .sidebar-module-meta { color: #6b7b96; font-size: .72rem; }

    /* Lesson rows: quieter default, unmistakable active state */
    .sidebar-lesson {
      padding: .7rem 1.1rem;
      border-bottom: 1px solid #f4f6fa;
      border-left: 3px solid transparent;
      transition: background .16s var(--ease), border-color .16s var(--ease);
    }
    .sidebar-lesson:hover:not(.locked) { background: #f7f9fd; transform: none; }
    .sidebar-lesson.active {
      background: linear-gradient(90deg, #eaf2ff 0%, #f6f9ff 100%);
      border-left-color: var(--blue);
      box-shadow: none;
    }
    .sidebar-lesson.active .lesson-info-title { font-weight: 700; color: var(--blue); }
    .sidebar-lesson.completed { background: transparent; border-left-color: transparent; }
    .sidebar-lesson.completed .lesson-info-title { color: #6b7b96; }
    .sidebar-lesson.completed .lesson-status { color: #10b981; }
    .sidebar-lesson.locked { opacity: .5; }

    /* --- Content surfaces --- */
    .lesson-card, .video-info-bar, .tab-panel, .study-note {
      border-radius: var(--r-lg);
    }
    .lesson-card {
      background: var(--surface);
      border: 1px solid var(--hairline);
      box-shadow: var(--e2);
    }
    .video-lesson-title {
      letter-spacing: -.02em;
      font-weight: 700;
      line-height: 1.25;
    }

    /* Tabs: a real moving indicator instead of a colour swap */
    .tab-btn {
      position: relative;
      transition: color .18s var(--ease);
      letter-spacing: .005em;
    }
    .tab-btn::after {
      content: '';
      position: absolute;
      left: 0; right: 0; bottom: -1px;
      height: 2.5px;
      border-radius: 3px 3px 0 0;
      background: var(--blue);
      transform: scaleX(0);
      transition: transform .22s var(--ease);
    }
    .tab-btn.active::after { transform: scaleX(1); }

    /* Reading column: comfortable measure and rhythm */
    .tab-panel p, .study-note p { line-height: 1.75; }
    .study-note h3 { letter-spacing: -.015em; }
    .study-note table {
      border-collapse: separate; border-spacing: 0;
      border: 1px solid var(--hairline);
      border-radius: var(--r-md);
      overflow: hidden;
      width: 100%;
    }
    .study-note th {
      background: #f5f8fd; font-weight: 700;
      font-size: .84rem; letter-spacing: .01em;
      text-align: left; padding: .6rem .8rem;
      border-bottom: 1px solid var(--hairline);
    }
    .study-note td { padding: .6rem .8rem; border-bottom: 1px solid #f2f5fa; }
    .study-note tr:last-child td { border-bottom: none; }

    /* Every authored note opens with
         <div class="revision-banner"><strong>Title</strong><span>Lesson note</span></div>
       but that class had no styling anywhere, so it rendered as one run-on
       line ("Welcome to the ProgramLesson note") sitting directly above the
       very same title repeated as a heading. Present it as a slim context
       bar so it reads as a label rather than a duplicated title. */
    .overview-text .revision-banner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: .75rem;
      flex-wrap: wrap;
      margin: 0 0 1.1rem;
      padding: .55rem .85rem;
      background: #f5f8fd;
      border: 1px solid var(--hairline);
      border-radius: 10px;
    }
    .overview-text .revision-banner strong {
      font-size: .73rem; font-weight: 700;
      letter-spacing: .06em; text-transform: uppercase;
      color: #5b6b8c;
    }
    .overview-text .revision-banner span {
      font-size: .68rem; font-weight: 700;
      letter-spacing: .05em; text-transform: uppercase;
      color: var(--blue); background: #e8f0fe;
      border-radius: 999px; padding: .22rem .62rem;
      white-space: nowrap;
    }

    /* Wider reading column so both the video and the notes get more room.
       The player is sized from leftover viewport height so the note still
       begins on the first screen; the reserve was 430px against a 420px
       floor, which collapsed to the floor on a 1366x768 laptop and rendered
       the video 494px wide beside a 900px card. A 210px reserve with a 640px
       floor, against the wider column, gives:
         1280x720   420 -> 800px
         1366x768   494 -> 885px
         1920x1080  900 -> 1040px
       Mobile is untouched: 100% still wins there. */
    :root { --content-w: 1200px; }
    .video-container {
      width: min(100%, var(--content-w),
                 max(700px, calc((100vh - var(--topbar-h) - 170px) * 16 / 9)));
      border-radius: var(--r-lg);
      box-shadow: var(--e3);
    }

    /* --- Note typography ---
       The authored notes are the part learners actually revise from, but the
       body text was 0.95rem (~15px) — small for long-form reading, and
       smaller than the interface around it. Raise it to ~17px with a more
       generous line-height, and scale the headings, lists and tables with
       it. The measure is capped in ch (not px) so it tracks the font size
       and lines stay in the comfortable 65-75 character range instead of
       stretching across the wider column. */
    .overview-text { max-width: 100%; font-size: 1.14rem; }
    .overview-text p,
    .overview-text li {
      font-size: 1.14rem;
      line-height: 1.85;
      color: #2c3a4f;
    }
    .overview-text p { margin-bottom: 1.05rem; }
    /* Earlier this capped the measure at 72ch for classic readability, but on
       a 1200px column that left ~310px of dead space to the right and pushed
       the page 2600px tall — the note read as a narrow ribbon and needed far
       more scrolling. Let the text use the column it is given; the wider
       column plus the larger type is the layout that was actually asked for. */
    .overview-text .lesson-note-intro,
    .overview-text .lesson-note-section > p,
    .overview-text .lesson-note-example,
    .overview-text .lesson-note-action,
    .overview-text .study-note > p { max-width: 100%; }
    .overview-text .study-note { max-width: 100%; }
    .overview-text h3 { font-size: 1.65rem; line-height: 1.3; margin-bottom: .55rem; }
    .overview-text h4 { font-size: 1.22rem; line-height: 1.4; }
    .overview-text .lesson-note-intro { font-size: 1.14rem; line-height: 1.8; }
    .overview-text .lesson-note-intro span,
    .overview-text .lesson-note-example { font-size: 1.12rem; line-height: 1.8; }
    .overview-text ul, .overview-text ol { padding-left: 1.35rem; }
    .overview-text li { margin-bottom: .5rem; }
    .overview-text table { font-size: 1.06rem; }
    .study-note th { font-size: 1rem; padding: .7rem .9rem; }
    .study-note td { padding: .7rem .9rem; line-height: 1.7; }
    .overview-text blockquote {
      font-size: 1.12rem; line-height: 1.8;
      border-left: 4px solid var(--gold);
      background: #fffbeb; color: #6b4a10;
      padding: .9rem 1.1rem; border-radius: 0 10px 10px 0;
      margin: 1.2rem 0; max-width: 100%;
    }
    .video-lesson-title { font-size: 1.5rem; }

    /* --- Keyboard accessibility: nothing above defined a focus style --- */
    a:focus-visible, button:focus-visible,
    .sidebar-lesson:focus-visible, .tab-btn:focus-visible {
      outline: none;
      box-shadow: var(--ring);
      border-radius: var(--r-sm);
    }

    /* --- Respect users who ask for less motion --- */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: .001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .001ms !important;
        scroll-behavior: auto !important;
      }
    }

    /* COURSE PLAYER 2026 — mobile-first learning refinement */
    .topbar{min-height:var(--topbar-h);height:auto;padding-inline:clamp(.75rem,2vw,1.35rem)}
    .btn-contents{min-height:44px;border-radius:12px;padding:.55rem .8rem;background:#f7f9fd;border-color:#dce5f2}
    .btn-contents-icon{font-size:1.05rem;line-height:1}
    .progress-wrap{padding:.38rem .55rem;border:1px solid #e3eaf4;border-radius:999px;background:#f8fafd}
    .progress-pct{color:#075f47;font-variant-numeric:tabular-nums}
    .video-info-bar{margin-top:.8rem;border:1px solid var(--hairline);border-bottom:0;border-radius:16px 16px 0 0;background:#fff}
    .tabs-bar{position:sticky;top:0;z-index:40;border:1px solid var(--hairline);border-top:0;background:rgba(255,255,255,.97);box-shadow:0 5px 14px rgba(2,24,68,.05);scrollbar-width:none}
    .tabs-bar::-webkit-scrollbar{display:none}.tab-btn{flex:1 0 auto}
    .tab-panel{border:1px solid var(--hairline);border-top:0;min-height:180px}
    .overview-text{color:#26364d;font-size:1rem;line-height:1.82}
    .overview-text h2,.overview-text h3,.overview-text h4{scroll-margin-top:70px;text-wrap:balance}
    .overview-text h3{color:var(--blue);font-size:1.2rem;line-height:1.35;margin:1.45rem 0 .65rem}
    .overview-text h4{font-size:1rem;line-height:1.4;margin-top:1.3rem}
    .overview-text p,.overview-text li{font-size:1rem;line-height:1.82}
    .lesson-nav-bar{margin-bottom:max(1rem,env(safe-area-inset-bottom));border:1px solid var(--hairline)}
    .btn-mark-complete{min-height:48px;padding-inline:1.2rem}
    .btn-prev-lesson,.btn-next-lesson{min-height:48px}
    .btn-prev-lesson:focus-visible,.btn-next-lesson:focus-visible,.btn-mark-complete:focus-visible,.tab-btn:focus-visible,.btn-contents:focus-visible{outline:3px solid rgba(21,101,216,.32);outline-offset:2px}
    @media(max-width:768px){
      :root{--topbar-h:68px}.topbar{gap:.55rem}.topbar-left{gap:.45rem;min-width:0}.topbar-divider{display:none}.topbar-brand{font-size:.88rem}
      .topbar-center{justify-content:flex-end;gap:.45rem}.progress-wrap{padding:.35rem .48rem}.progress-bar-track{width:clamp(48px,13vw,70px)}
      .topbar-right{gap:.35rem}.topbar-avatar{width:40px;height:40px}.video-scroll{padding:0 .7rem;scroll-padding-top:58px}
      .video-container{width:100%;margin-top:.75rem;border-radius:16px}.video-info-bar,.tabs-bar,.tab-panel,.lesson-nav-bar{width:100%}
      .video-info-bar{padding:.9rem 1rem .75rem}.video-lesson-title{font-size:clamp(1.08rem,4.7vw,1.3rem)}
      .video-lesson-meta{margin-top:.4rem;gap:.7rem;flex-wrap:wrap}.tabs-bar{border-radius:0;padding:0 .25rem}
      .tab-btn{padding:.82rem .72rem;font-size:.82rem}.tab-panel{padding:1.15rem 1rem 1.35rem}
      .overview-text p,.overview-text li{font-size:1rem;line-height:1.84}
      .overview-text>p,.overview-text li,.overview-text>blockquote,.overview-text .lesson-note-intro,.overview-text .lesson-note-section>p,.overview-text .lesson-note-example,.overview-text .lesson-note-action{max-width:none}
      .lesson-nav-bar{margin-top:.75rem;margin-bottom:1.2rem;border-radius:16px}.btn-mark-complete{font-size:.92rem}
    }
    @media(max-width:520px){
      :root{--topbar-h:64px}.topbar{padding-inline:.55rem;gap:.35rem}.topbar-back{min-width:42px;padding:.35rem;justify-content:center;font-size:1.15rem}
      .topbar-brand{display:none}.btn-contents{width:44px;padding:.5rem;justify-content:center}.btn-contents-label{display:none}
      .progress-wrap{border:0;background:transparent;padding:0}.progress-bar-track{display:none}.progress-pct{font-size:.71rem}
      .topbar-avatar{width:38px;height:38px}.video-scroll{padding-inline:.45rem}.video-container{border-radius:13px}
      .video-info-bar{margin-top:.55rem;padding:.82rem .85rem .7rem}.tab-panel{padding:1.05rem .85rem 1.25rem}
      .overview-text p,.overview-text li{font-size:1.01rem;line-height:1.88}.overview-text .lesson-note-section{margin-top:1.4rem;padding-top:1.15rem}
      .lesson-nav-bar{padding:.65rem;gap:.5rem}.btn-prev-lesson,.btn-next-lesson,.btn-mark-complete{min-height:50px}
      .lesson-progress-dots{padding:.2rem 0}.lock-toast{width:calc(100% - 1.5rem);white-space:normal;text-align:center}
    }
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

    /* Long-lesson reading tools */
    .lesson-reading-progress{position:fixed;top:var(--topbar-h);left:var(--sidebar-w);right:0;height:4px;z-index:997;background:rgba(219,228,241,.72);pointer-events:none}
    .lesson-reading-progress-fill{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--blue),#1565d8,var(--red));box-shadow:0 0 8px rgba(21,101,216,.35);transition:width .12s linear}
    .back-to-lesson-top{position:fixed;right:1.15rem;bottom:1.15rem;z-index:120;width:48px;height:48px;border:1px solid #d7e2f1;border-radius:50%;background:#fff;color:var(--blue);box-shadow:0 8px 24px rgba(2,24,68,.18);font:800 1.25rem/1 Inter,sans-serif;display:grid;place-items:center;cursor:pointer;opacity:0;visibility:hidden;transform:translateY(12px);transition:opacity .2s,transform .2s,visibility .2s}
    .back-to-lesson-top.show{opacity:1;visibility:visible;transform:translateY(0)}
    .back-to-lesson-top:hover{background:var(--blue);color:#fff;transform:translateY(-2px)}
    .back-to-lesson-top:focus-visible{outline:3px solid rgba(21,101,216,.32);outline-offset:3px}
    @media(max-width:768px){.lesson-reading-progress{left:0}.back-to-lesson-top{right:.8rem;bottom:.8rem;width:46px;height:46px}}
    @media(prefers-reduced-motion:reduce){.lesson-reading-progress-fill,.back-to-lesson-top{transition:none}}

    /* Computer Literacy: compact, touch-friendly glossary cards. */
    .overview-text .lesson-keywords {
      margin-top: 1.4rem;
      padding: 1rem;
      border: 1px solid #cdddf3;
      border-radius: 14px;
      background: linear-gradient(145deg, #f7fbff, #eef5ff);
    }
    .overview-text .lesson-keywords h4 { margin: 0; color: var(--navy); }
    .overview-text .lesson-keywords-hint {
      margin: .3rem 0 .8rem;
      color: #5d6d86;
      font-size: .84rem;
    }
    .overview-text .lesson-keyword-grid { display: grid; gap: .55rem; }
    .overview-text .lesson-keyword {
      border: 1px solid #d5e2f4;
      border-radius: 10px;
      background: #fff;
      overflow: hidden;
    }
    .overview-text .lesson-keyword summary {
      min-height: 44px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: .75rem;
      padding: .65rem .8rem;
      color: var(--navy);
      font-weight: 750;
      cursor: pointer;
      list-style: none;
    }
    .overview-text .lesson-keyword summary::-webkit-details-marker { display: none; }
    .overview-text .lesson-keyword summary::after {
      content: '+';
      width: 1.55rem;
      height: 1.55rem;
      display: grid;
      place-items: center;
      flex: 0 0 auto;
      border-radius: 50%;
      color: #fff;
      background: var(--blue);
      font-size: 1rem;
      line-height: 1;
    }
    .overview-text .lesson-keyword[open] summary::after { content: '−'; }
    .overview-text .lesson-keyword p {
      max-width: none;
      margin: 0;
      padding: .75rem .8rem .85rem;
      border-top: 1px solid #e7eef8;
      color: #34445c;
      background: #fbfdff;
    }


    /* Computer Literacy visual-identification panels */
    .overview-text .cl-lesson-visual {
      margin: 1rem 0 1.35rem;
      border: 1px solid #c9daf1;
      border-radius: 16px;
      overflow: hidden;
      background: #fff;
      box-shadow: 0 8px 24px rgba(3, 41, 96, .08);
    }
    .overview-text .cl-visual-title {
      padding: .75rem 1rem;
      color: #fff;
      background: linear-gradient(120deg, var(--navy), var(--blue));
      font-size: .9rem;
      font-weight: 800;
    }
    .overview-text .cl-visual-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
      gap: .65rem;
      padding: .85rem;
    }
    .overview-text .cl-visual-item {
      min-width: 0;
      padding: .8rem .55rem;
      text-align: center;
      border: 1px solid #dce7f5;
      border-radius: 12px;
      background: #f7faff;
    }
    .overview-text .cl-visual-item span {
      display: block;
      margin-bottom: .35rem;
      font-size: 2rem;
      line-height: 1;
    }
    .overview-text .cl-visual-item strong,
    .overview-text .cl-visual-item small { display: block; }
    .overview-text .cl-visual-item strong { color: var(--navy); font-size: .85rem; }
    .overview-text .cl-visual-item small { margin-top: .25rem; color: #64748b; font-size: .7rem; line-height: 1.35; }
    .overview-text .cl-flow {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: .4rem;
      padding: 1rem .7rem;
      overflow-x: auto;
    }
    .overview-text .cl-flow-item {
      min-width: 68px;
      padding: .65rem .45rem;
      text-align: center;
      border-radius: 10px;
      background: #eff5ff;
      border: 1px solid #d5e3f7;
    }
    .overview-text .cl-flow-item span,
    .overview-text .cl-flow-item strong { display: block; }
    .overview-text .cl-flow-item span { font-size: 1.65rem; }
    .overview-text .cl-flow-item strong { margin-top: .25rem; color: var(--navy); font-size: .68rem; }
    .overview-text .cl-flow > b { color: var(--blue); font-size: 1.1rem; }
    .overview-text .cl-lesson-visual figcaption {
      padding: .7rem .9rem;
      border-top: 1px solid #e3ebf6;
      color: #4c5d73;
      background: #fbfdff;
      font-size: .78rem;
      line-height: 1.5;
    }
    @media (max-width: 480px) {
      .overview-text .cl-visual-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .overview-text .cl-flow { justify-content: flex-start; }
    }


    /* IELTS Writing Task 1 data visuals and model observations */
    .overview-text .ielts-chart-wrap { padding: 1rem; overflow-x: auto; }
    .overview-text .ielts-svg-chart { display: block; width: 100%; max-width: 520px; height: auto; margin: 0 auto; }
    .overview-text .ielts-model-line { margin-top: .65rem; padding: .65rem .75rem; border-left: 4px solid var(--red); border-radius: 7px; background: #fff4f5; color: #313c50; }
    .overview-text .ielts-pie-row { display: flex; align-items: center; justify-content: center; gap: 1.25rem; flex-wrap: wrap; }
    .overview-text .ielts-pie { width: 170px; aspect-ratio: 1; border-radius: 50%; background: conic-gradient(#0d3d7a 0 40%, #1769d2 40% 70%, #e51d2a 70% 90%, #f3b33d 90%); box-shadow: inset 0 0 0 2px #fff; }
    .overview-text .ielts-pie-row ul { margin: 0; padding: 0; list-style: none; }
    .overview-text .ielts-pie-row li { margin: .35rem 0; }
    .overview-text .swatch { display: inline-block; width: .8rem; height: .8rem; margin-right: .4rem; border-radius: 3px; }
    .overview-text .swatch.s1 { background:#0d3d7a; }.overview-text .swatch.s2 { background:#1769d2; }.overview-text .swatch.s3 { background:#e51d2a; }.overview-text .swatch.s4 { background:#f3b33d; }
    .overview-text .ielts-sample-table table { min-width: 380px; margin: 0 auto; }
    .overview-text .ielts-process,.overview-text .ielts-map-change { display:flex; align-items:center; justify-content:center; gap:.55rem; min-width:520px; }
    .overview-text .ielts-process span { display:grid; place-items:center; gap:.35rem; min-width:90px; padding:.75rem; border:1px solid #d7e4f6; border-radius:12px; background:#f5f9ff; font-size:1.8rem; }
    .overview-text .ielts-process b { font-size:.7rem; color:var(--navy); }
    .overview-text .ielts-map-change section { min-width:205px; padding:.8rem; text-align:center; border:1px solid #d7e4f6; border-radius:12px; background:#f7faff; line-height:1.9; }
    .overview-text .ielts-map-change section>b { display:block; margin-bottom:.3rem; color:var(--navy); }
    .overview-text .ielts-task-structure { display:grid; gap:.55rem; max-width:620px; margin:auto; }
    .overview-text .ielts-task-structure span { display:grid; grid-template-columns:2rem 1fr; padding:.7rem; border:1px solid #d7e4f6; border-radius:10px; background:#f7faff; color:var(--navy); font-weight:700; }
    .overview-text .ielts-task-structure span>b { grid-row:1/3; display:grid; place-items:center; color:#fff; background:var(--blue); border-radius:50%; }
    .overview-text .ielts-task-structure small { color:#607089; font-weight:500; }
    .overview-text .ielts-language-scale,.overview-text .ielts-analysis-path { display:grid; gap:.5rem; max-width:620px; margin:auto; }
    .overview-text .ielts-language-scale span,.overview-text .ielts-analysis-path span { padding:.7rem .8rem; border:1px solid #dbe6f4; border-radius:9px; background:#f8fbff; color:#263b59; }
    .overview-text .ielts-language-scale b { display:inline-block; min-width:2rem; color:var(--red); font-size:1.15rem; }
    .overview-text .ielts-compare { display:grid; grid-template-columns:repeat(3,1fr); gap:.65rem; }
    .overview-text .ielts-compare div { padding:.8rem; text-align:center; border-radius:11px; background:#f4f8fe; border:1px solid #d8e4f5; }
    .overview-text .ielts-compare b,.overview-text .ielts-compare strong { display:block; }
    .overview-text .ielts-compare b { color:var(--red); font-size:.72rem; text-transform:uppercase; }.overview-text .ielts-compare strong { margin-top:.3rem; color:var(--navy); font-size:.83rem; }
    @media(max-width:520px){.overview-text .ielts-compare{grid-template-columns:1fr}.overview-text .ielts-pie{width:145px}}


.ml-note{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#25364a;line-height:1.75;font-size:1rem}.ml-note h2{color:#001d4a;font-size:clamp(1.55rem,5vw,2.3rem);line-height:1.14}.ml-note h3{color:#00336d;margin-top:2rem;font-size:1.35rem}.ml-banner{background:linear-gradient(135deg,#001d4a,#0b4d86 72%,#c5202f);color:#fff;border-radius:20px;padding:1.15rem 1.25rem;display:flex;flex-direction:column;gap:.25rem;box-shadow:0 12px 30px rgba(0,29,74,.22)}.ml-banner span{font-size:.72rem;letter-spacing:.14em;font-weight:800}.ml-banner strong{font-size:1.2rem}.ml-banner small{opacity:.88}.ml-kicker{color:#c5202f;font-size:.78rem;font-weight:900;letter-spacing:.17em}.ml-table{overflow-x:auto}.ml-note table{width:100%;border-collapse:collapse;margin:1rem 0}.ml-note th,.ml-note td{border:1px solid #cad8e8;padding:.78rem;text-align:left;vertical-align:top}.ml-note th{background:#eaf3fd;color:#001d4a}.ml-scope,.ml-definition,.ml-example,.ml-standard,.ml-reminder{padding:1rem 1.1rem;border-radius:0 14px 14px 0;border-left:5px solid #0b4d86;background:#f1f7fd;margin:1rem 0}.ml-scope,.ml-reminder{border-color:#c5202f;background:#fff4f4}.ml-standard{border-color:#e7a500;background:#fff8df}.ml-figure{margin:1.5rem 0}.ml-figure svg{display:block;width:100%;height:auto;border-radius:18px;box-shadow:0 12px 30px rgba(0,29,74,.18)}.ml-figure figcaption{color:#5f6f82;font-size:.88rem;margin-top:.55rem}.ml-keywords{background:#eaf6ff;border:1px solid #b9d7f2;border-radius:18px;padding:1rem;margin-top:1.5rem}.ml-keywords h3{margin-top:.2rem}.ml-note details{background:#fff;border:1px solid #cbd8e7;border-radius:12px;margin:.7rem 0}.ml-note summary{cursor:pointer;color:#00336d;font-weight:800;padding:.9rem 1rem}.ml-note details p{padding:0 1rem 1rem;margin:0}.ml-mcq{background:#f8fafc;border:1px solid #d5e0ec;border-radius:16px;padding:1rem;margin:1rem 0}.ml-short{border-top:3px solid #dce7f2}.ml-note li{margin:.35rem 0}@media(max-width:600px){.ml-note{font-size:1rem}.ml-note h3{font-size:1.3rem}.ml-note th,.ml-note td{padding:.65rem}.ml-banner{padding:1rem}}@media print{.ml-note details>*{display:block}.ml-reminder{break-inside:avoid}}
